import http.client, json, re
hosts=['172.17.0.2','172.17.0.3','172.17.0.4','172.17.0.5','172.17.0.6','172.17.0.7','172.17.0.8','172.17.0.9']
paths=['/health','/info']
ports=[9000]

def fetch(host, port, path):
    conn=http.client.HTTPConnection(host, port, timeout=2)
    try:
        conn.request('GET', path, headers={'User-Agent':'OpenClaw-service-ident/1.0','Accept':'application/json,text/plain,*/*'})
        r=conn.getresponse()
        body=r.read(4096)
        ctype=r.getheader('content-type') or ''
        server=r.getheader('server') or ''
        text=body.decode('utf-8','replace')
        return {'status':r.status,'reason':r.reason,'ctype':ctype,'server':server,'body':text}
    except Exception as e:
        return {'error':type(e).__name__+': '+str(e)}
    finally:
        try: conn.close()
        except: pass

def summarize(resp):
    if 'error' in resp:
        return 'ERROR '+resp['error']
    body=resp.get('body','')
    ident=[]
    if resp.get('server'): ident.append('Server='+resp['server'])
    # Try JSON fields commonly carrying service identity
    try:
        data=json.loads(body)
        def walk(x, prefix=''):
            out=[]
            if isinstance(x, dict):
                for k,v in x.items():
                    key=(prefix+'.'+k if prefix else k)
                    lk=k.lower()
                    if lk in ('name','service','service_name','app','application','version','build','description','status') and not isinstance(v,(dict,list)):
                        out.append(f'{key}={v}')
                    out += walk(v,key)
            elif isinstance(x, list):
                for i,v in enumerate(x[:5]): out += walk(v, prefix+f'[{i}]')
            return out
        ident += walk(data)
    except Exception:
        pass
    # Text patterns
    for pat in [r'(?:service|app|application|name)\s*[:=]\s*([\w .:/-]{1,80})', r'(?:version)\s*[:=]\s*([\w .:/-]{1,80})']:
        for m in re.finditer(pat, body, re.I):
            ident.append(m.group(0).strip())
    snippet=' '.join(body.split())[:240]
    base=f"HTTP {resp['status']} {resp['reason']} ctype={resp.get('ctype','') or '-'}"
    if ident:
        return base+' | '+ '; '.join(dict.fromkeys(ident))
    if snippet:
        return base+' | body="'+snippet+'"'
    return base+' | empty body'

for host in hosts:
    for port in ports:
        print(f'## {host}:{port}')
        for path in paths:
            resp=fetch(host,port,path)
            print(f'{path}: {summarize(resp)}')
        print()
